import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import About from "./components/About";
import Skills from "./components/Skills";
import Projects from "./components/Projects";
import CVSection from "./components/CVSection";
import Contact from "./components/Contact";
import Footer from "./components/Footer";
import CareerGoals from "./components/CareerGoals";

export default function App() {
  const { i18n } = useTranslation();

  // 1) Thème en premier (évite le "Cannot access 'theme' before initialization")
  const [theme, setTheme] = useState(() => {
    try {
      return localStorage.getItem("portfolio_theme") || "light";
    } catch {
      return "light";
    }
  });

  useEffect(() => {
    const root = document.documentElement; // <html>
    if (theme === "dark") root.classList.add("dark");
    else root.classList.remove("dark");
    localStorage.setItem("portfolio_theme", theme);
  }, [theme]);

  // 2) Langue ensuite
  const [lang, setLang] = useState(() => {
    try {
      const saved = (localStorage.getItem("portfolio_lang") || i18n.language || "fr").toLowerCase();
      return saved === "en" ? "en" : "fr";
    } catch {
      return "fr";
    }
  });

  useEffect(() => {
    i18n.changeLanguage(lang);
    localStorage.setItem("portfolio_lang", lang);
  }, [lang, i18n]);

  // 3) Contexte
  const ctx = useMemo(() => ({ lang, setLang, theme, setTheme }), [lang, theme]);

  return (
    <div className="min-h-screen bg-gray-50 text-slate-900 dark:bg-gray-950 dark:text-slate-100 transition-colors">
      <Navbar ctx={ctx} />
      <main>
        <Hero />
        <About />
        <CareerGoals />
        <Skills />
        <Projects />
        <CVSection />
        <Contact />
      </main>
      <Footer />
    </div>
  );
}
