import { useState } from "react";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";

// 1) Mets ton endpoint Formspree ici si tu en as un (ex: "https://formspree.io/f/mdkwveyb")
//    CRA: utilise REACT_APP_FORMSPREE_ENDPOINT dans .env
//    Vite: utilise VITE_FORMSPREE_ENDPOINT
const ENV_ENDPOINT =
  (typeof import.meta !== "undefined" && import.meta.env?.VITE_FORMSPREE_ENDPOINT) ||
  process.env.REACT_APP_FORMSPREE_ENDPOINT ||
  ""; // ← reste vide = fallback mailto

export default function Contact() {
  const { t } = useTranslation();
  const [state, setState] = useState({ loading: false, ok: false, error: "" });

  async function onSubmit(e) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);

    const name = data.get("name")?.toString() || "";
    const email = data.get("email")?.toString() || "";
    const message = data.get("message")?.toString() || "";

    // Validation simple
    if (!name || !email || !message) {
      setState({ loading: false, ok: false, error: "Veuillez remplir tous les champs." });
      return;
    }

    // 2) Si pas de Formspree -> fallback mailto
    if (!ENV_ENDPOINT) {
      const subject = encodeURIComponent(`Message depuis le portfolio - ${name}`);
      const body = encodeURIComponent(`${message}\n\n— ${name} <${email}>`);
      window.location.href = `mailto:mireilledipama5@gmail.com?subject=${subject}&body=${body}`;
      setState({ loading: false, ok: true, error: "" });
      form.reset();
      return;
    }

    // 3) Envoi via Formspree
    try {
      setState({ loading: true, ok: false, error: "" });
      const res = await fetch(ENV_ENDPOINT, {
        method: "POST",
        headers: { Accept: "application/json" },
        body: data,
      });
      if (res.ok) {
        form.reset();
        setState({ loading: false, ok: true, error: "" });
      } else {
        const json = await res.json().catch(() => ({}));
        setState({ loading: false, ok: false, error: json?.error || "Erreur d’envoi." });
      }
    } catch (err) {
      setState({ loading: false, ok: false, error: String(err) });
    }
  }

  return (
    <section id="contact" className="container section">
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="section-title"
      >
        {t("nav.contact")}
      </motion.h2>

      <motion.form
        onSubmit={onSubmit}
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="grid gap-4 max-w-2xl card p-6"
      >
        <div className="grid sm:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm mb-1">Nom</label>
            <input name="name" required className="w-full rounded-xl border border-slate-300 dark:border-slate-700 bg-transparent px-3 py-2" />
          </div>
          <div>
            <label className="block text-sm mb-1">Email</label>
            <input type="email" name="email" required className="w-full rounded-xl border border-slate-300 dark:border-slate-700 bg-transparent px-3 py-2" />
          </div>
        </div>
        <div>
          <label className="block text-sm mb-1">Message</label>
          <textarea name="message" rows={5} required className="w-full rounded-xl border border-slate-300 dark:border-slate-700 bg-transparent px-3 py-2" />
        </div>

        <div className="flex items-center gap-3">
          <button disabled={state.loading} className="btn btn-primary">
            {state.loading ? "Envoi..." : "Envoyer"}
          </button>
          <a href="mailto:mireilledipama5@gmail.com" className="btn btn-ghost">Ou m’écrire</a>
        </div>

        {state.ok && <p className="text-sm text-green-600">Merci ! Votre message a été envoyé ✔</p>}
        {state.error && <p className="text-sm text-red-600">Erreur : {state.error}</p>}

        {!ENV_ENDPOINT && (
          <p className="text-xs text-muted">
            Astuce : Merci pour la confiance!
          </p>
        )}
      </motion.form>
    </section>
  );
}
