import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";

export default function CVSection() {
  const { t } = useTranslation();

  return (
    <section id="cv" className="container py-20">
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="text-3xl font-bold mb-6"
      >
        {t("nav.cv")}
      </motion.h2>

      <div className="flex flex-wrap items-center gap-4 mb-6">
        <a href="%PUBLIC_URL%/cv/CV_fr.pdf" download className="btn btn-primary">
          {t("actions.download_cv")}
        </a>
        <a href="/cv/CV_fr.pdf" target="_blank" rel="noreferrer" className="btn btn-ghost">
          Ouvrir dans un onglet
        </a>
      </div>

      <div className="rounded-2xl overflow-hidden border border-slate-200 dark:border-slate-800">
        {/* Aperçu PDF (affichage basique) */}
        <iframe
          title="CV Preview"
          src="%PUBLIC_URL%/cv/CV_fr.pdf"
          className="w-full"
          style={{ minHeight: "75vh" }}
        />
      </div>
    </section>
  );
}
