import { useState } from "react";
import { useTranslation } from "react-i18next";

const IconLinkedIn = (props) => (
  <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true" {...props}>
    <path d="M4.98 3.5C4.98 4.88 3.86 6 2.5 6S0 4.88 0 3.5 1.12 1 2.5 1 4.98 2.12 4.98 3.5zM.5 8.5h4V24h-4V8.5zM8.5 8.5h3.8v2.11h.06c.53-1 1.84-2.11 3.78-2.11 4.04 0 4.79 2.66 4.79 6.11V24h-4v-6.88c0-1.64-.03-3.75-2.29-3.75-2.29 0-2.64 1.79-2.64 3.63V24h-4V8.5z" />
  </svg>
);
const IconGitHub = (props) => (
  <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true" {...props}>
    <path d="M12 .5A11.5 11.5 0 0 0 .5 12.15c0 5.17 3.35 9.56 8 11.11.58.1.79-.26.79-.57 0-.28-.01-1.02-.02-2-3.26.72-3.95-1.58-3.95-1.58-.53-1.37-1.3-1.73-1.3-1.73-1.06-.74.08-.73.08-.73 1.18.08 1.8 1.21 1.8 1.21 1.04 1.84 2.74 1.31 3.41 1 .11-.77.41-1.31.75-1.61-2.6-.3-5.34-1.33-5.34-5.9 0-1.3.46-2.37 1.21-3.21-.12-.3-.52-1.52.11-3.17 0 0 .98-.32 3.22 1.22a11.14 11.14 0 0 1 5.86 0c2.24-1.54 3.21-1.22 3.21-1.22.64 1.65.24 2.87.12 3.17.76.84 1.2 1.91 1.2 3.21 0 4.58-2.75 5.6-5.36 5.9.43.37.81 1.1.81 2.22 0 1.6-.02 2.89-.02 3.28 0 .31.21.68.8.56a11.5 11.5 0 0 0 7.94-11.1A11.5 11.5 0 0 0 12 .5z" />
  </svg>
);
const IconMenu = (props) => (
  <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
    <path d="M3 6h18M3 12h18M3 18h18" />
  </svg>
);
const IconClose = (props) => (
  <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
    <path d="M6 6l12 12M6 18L18 6" />
  </svg>
);

export default function Navbar({ ctx }) {
  const { t } = useTranslation();
  const { lang, setLang, theme, setTheme } = ctx;
  const [open, setOpen] = useState(false);

  const toggleLang = () => setLang(lang === "fr" ? "en" : "fr");
  const toggleTheme = () => setTheme(theme === "dark" ? "light" : "dark");

  const NavLinks = ({ onClick }) => (
    <>
      <a href="#home" className="nav-link" onClick={onClick}>{t("nav.home")}</a>
      <a href="#about" className="nav-link" onClick={onClick}>{t("nav.about")}</a>
      <a href="#career" className="nav-link">Objectif</a>
      <a href="#skills" className="nav-link" onClick={onClick}>{t("nav.skills")}</a>
      <a href="#projects" className="nav-link" onClick={onClick}>{t("nav.projects")}</a>
      <a href="#cv" className="nav-link" onClick={onClick}>{t("nav.cv")}</a>
      <a href="#contact" className="nav-link" onClick={onClick}>{t("nav.contact")}</a>
    </>
  );

  return (
    <header className="sticky top-0 z-40 bg-white/90 dark:bg-gray-950/85 backdrop-blur border-b border-slate-200 dark:border-slate-800">
      <div className="container h-16 flex items-center justify-between">
        <a href="#home" className="font-extrabold text-lg tracking-tight"> {t("brand")} </a>

        {/* Desktop */}
        <nav className="hidden md:flex items-center gap-6">
          <NavLinks />
        </nav>

        {/* Actions droite */}
        <div className="hidden md:flex items-center gap-2">
          <a href="https://www.linkedin.com/in/andr%C3%A9a-dipama-235b8a253/?originalSubdomain=ma" target="_blank" rel="noreferrer" className="btn btn-ghost !px-3" title={t("actions.open_linkedin")}><IconLinkedIn /></a>
          <a href="https://github.com/Madmire" target="_blank" rel="noreferrer" className="btn btn-ghost !px-3" title={t("actions.open_github")}><IconGitHub /></a>
          <button onClick={toggleLang} className="btn btn-ghost !px-3" title={t("toggles.language")}>{lang.toUpperCase()}</button>
          <button onClick={toggleTheme} className="btn btn-ghost !px-3" title={t("toggles.theme")}>{theme === "dark" ? t("toggles.light") : t("toggles.dark")}</button>
        </div>

        {/* Mobile toggler */}
        <button className="md:hidden btn btn-ghost !px-3" onClick={() => setOpen(!open)} aria-label="Menu">
          {open ? <IconClose /> : <IconMenu />}
        </button>
      </div>

      {/* Menu mobile */}
      {open && (
        <div className="md:hidden border-t border-slate-200 dark:border-slate-800">
          <div className="container py-3 flex flex-col gap-3">
            <NavLinks onClick={() => setOpen(false)} />
            <div className="flex items-center gap-2 pt-2">
              <a href="https://www.linkedin.com/in/andr%C3%A9a-dipama-235b8a253/?originalSubdomain=ma" target="_blank" rel="noreferrer" className="btn btn-ghost !px-3"><IconLinkedIn /></a>
              <a href="https://github.com/Madmire" target="_blank" rel="noreferrer" className="btn btn-ghost !px-3"><IconGitHub /></a>
              <button onClick={() => { toggleLang(); setOpen(false); }} className="btn btn-ghost !px-3">{lang.toUpperCase()}</button>
              <button onClick={() => { toggleTheme(); setOpen(false); }} className="btn btn-ghost !px-3">{theme === "dark" ? t("toggles.light") : t("toggles.dark")}</button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}
