import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import SkillsIcons from "./SkillsIcons";


const skills = [
  {
    cat: "🧠 Data & IA",
    list: ["Python 🐍", "Pandas", "Scikit-learn 🤖", "PySpark ⚡", "MLflow 📊"],
  },
  {
    cat: "🗄️ Big Data",
    list: ["Kafka 🌀", "Elasticsearch 🔍", "Hadoop 🌲", "Superset 📈"],
  },
  {
    cat: "☁️ Cloud & DevOps",
    list: ["Docker 🐳", "Azure ☁️", "GitHub Actions ⚙️"],
  },
  {
    cat: "💻 Web & API",
    list: ["FastAPI 🚀", "ReactJS ⚛️", "TailwindCSS 🎨"],
  },
  {
    cat: "🌍 Langues",
    list: ["Français 🇫🇷 (C1)", "Anglais 🇬🇧 (B2)", "Espagnol 🇪🇸 (A2)"],
  },
  {
    cat: "🎶 Passions",
    list: ["Mathématiques ➗", "Finance 💹", "Informatique 💻", "Musique / Chorale 🎤"],
  },
];

export default function Skills() {
  const { t } = useTranslation();

  return (
    <section id="skills" className="container section">
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="section-title"
      >
        {t("nav.skills")}
      </motion.h2>
      <SkillsIcons />


      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {skills.map(({ cat, list }) => (
          <motion.div
            key={cat}
            whileHover={{ scale: 1.02 }}
            className="card p-6"
          >
            <h3 className="font-semibold text-indigo-600 dark:text-indigo-400 mb-3 text-lg">
              {cat}
            </h3>
            <ul className="space-y-1 text-slate-700 dark:text-slate-300">
              {list.map((item) => (
                <li key={item} className="flex items-center gap-2">
                  <span>•</span> {item}
                </li>
              ))}
            </ul>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
