import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import QuoteRotator from "./QuoteRotator";


export default function Hero() {
  const { t } = useTranslation();

  const fadeUp = (d = 0) => ({
    initial: { opacity: 0, y: 14 },
    animate: { opacity: 1, y: 0, transition: { duration: 0.6, delay: d } },
  });

  return (
    <section id="home" className="relative overflow-hidden">
      {/* Fond animé discret */}
      <div className="absolute inset-0 -z-10 bg-gradient-soft" />

      <div className="container section grid items-center gap-10 md:grid-cols-2">
        {/* Zone texte */}
        <motion.div {...fadeUp(0.05)}>
          <p className="text-[11px] uppercase tracking-[0.22em] text-muted">
            {t("hero.greeting")}
          </p>
          <h1 className="mt-2 text-4xl md:text-5xl font-extrabold tracking-tight">
            {t("brand")}{" "}
            <span className="text-indigo-600 dark:text-indigo-400">— {t("role")}</span>
          </h1>
          <p className="mt-4 text-lg text-slate-700 dark:text-slate-300 max-w-xl">
            {t("hero.punch")}
          </p>

          {/* Passions (tech minimal + perso) */}
          <div className="mt-5 flex flex-wrap gap-2">
            <span className="pill">Mathématiques</span>
            <span className="pill">Finance</span>
            <span className="pill">Informatique</span>
            <span className="pill">Musique / Chorale</span>
          </div>

          <div className="mt-7 flex flex-wrap gap-3">
            <a
              href="/cv/monCV.pdf"
              download
              className="btn btn-primary shadow-lg shadow-indigo-500/20 hover:shadow-indigo-600/40 transition-all"
            >
              {t("actions.download_cv")}
            </a>
            <a href="#projects" className="btn btn-ghost">
              {t("actions.view_projects")}
            </a>
          </div>
        </motion.div>

        {/* Portrait */}
        <motion.div {...fadeUp(0.12)} className="flex justify-center md:justify-end">
          <div className="relative">
            {/* halo soft */}
            <div className="absolute -inset-6 rounded-full blur-3xl opacity-30 bg-indigo-400/50 dark:bg-indigo-500/40" />
            <img
              src="/img/profile.jpg"
              alt="Portrait professionnel"
              className="relative h-56 w-56 md:h-64 md:w-64 rounded-full object-cover object-center ring-2 ring-indigo-500/20 shadow-2xl"
            />
            {/* ⬇️ Citation dynamique */}
            <QuoteRotator />

          </div>
        </motion.div>
      </div>
    </section>
  );
}
