import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";

const projects = [
  {
    name: "SmartBudget AI",
    desc: "Assistant intelligent de gestion financière pour étudiants, basé sur LangChain et Gemini 2.0 Flash.",
    tech: ["FastAPI", "LangChain", "MySQL", "HTML/CSS/JS"],
    img: "%PUBLIC_URL%/img/smartbudget.jpg",
    link: "https://github.com/Madmire/SmartBudgetAI",
  },
  {
    name: "Facebook Moderation System",
    desc: "Pipeline complet pour la modération automatique des pages Facebook médiatiques.",
    tech: ["Kafka", "Elasticsearch", "MLflow", "ReactJS"],
    img: "%PUBLIC_URL%/img/moderation.jpg",
    link: "https://github.com/ton-github/facebook-moderation",
  },
  {
    name: "IoT Real-time Pipeline",
    desc: "Simulation et traitement temps réel de données IoT via Kafka, Flink et Kibana.",
    tech: ["Kafka", "Flink", "Kibana", "Superset"],
    img: "%PUBLIC_URL%/img/iot-pipeline.jpg",
    link: "https://github.com/ton-github/iot-pipeline",
  },
];

export default function Projects() {
  const { t } = useTranslation();

  return (
    <section id="projects" className="container section">
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="section-title"
      >
        {t("nav.projects")}
      </motion.h2>

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
        {projects.map((p) => (
          <motion.div
            key={p.name}
            whileHover={{ scale: 1.03 }}
            transition={{ type: "spring", stiffness: 150 }}
            className="card overflow-hidden flex flex-col"
          >
            <div className="relative group">
              <img
                src={p.img}
                alt={p.name}
                className="h-40 w-full object-cover group-hover:opacity-90 transition"
              />
              <a
                href={p.link}
                target="_blank"
                rel="noreferrer"
                className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-sm transition"
              >
                Voir sur GitHub →
              </a>
            </div>

            <div className="p-4 flex-1 flex flex-col justify-between">
              <div>
                <h3 className="text-lg font-semibold text-indigo-600 dark:text-indigo-400">
                  {p.name}
                </h3>
                <p className="mt-2 text-sm text-slate-700 dark:text-slate-300">
                  {p.desc}
                </p>
              </div>

              <ul className="mt-3 flex flex-wrap gap-2 text-xs text-indigo-600 dark:text-indigo-300">
                {p.tech.map((t) => (
                  <li key={t} className="border border-indigo-500/30 rounded-full px-2 py-1">
                    {t}
                  </li>
                ))}
              </ul>
            </div>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
