export default function SkillsIcons() {
  const items = [
    { title: "Python", icon: <Python /> },
    { title: "Docker", icon: <Docker /> },
    { title: "Azure", icon: <Azure /> },
    { title: "Kafka", icon: <Kafka /> },
    { title: "Elasticsearch", icon: <Elasticsearch /> },
    { title: "React", icon: <ReactIcon /> },
    { title: "FastAPI", icon: <FastAPI /> },
    { title: "MLflow", icon: <MLflow /> },
    { title: "GitHub Actions", icon: <GHAction /> },
    { title: "TailwindCSS", icon: <Tailwind /> },
  ];

  return (
    <div className="mt-6 overflow-x-auto">
      <motion.div
        className="flex items-center gap-3 min-w-max"
        initial={{ opacity: 0, y: 8 }}
        whileInView={{ opacity: 1, y: 0 }}
      >
        {items.map(({ title, icon }) => (
          <Icon key={title} title={title}>{icon}</Icon>
        ))}
      </motion.div>
    </div>
  );
}
