import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { AnimatePresence, motion } from "framer-motion";

export default function QuoteRotator() {
  const { i18n } = useTranslation();

  // ✨ Personnalise les citations ici (FR/EN)
  const QUOTES = useMemo(
    () => ({
      fr: [
        "Celui qui doute de lui-même reste immobile, mais celui qui s’accorde sa confiance ouvre la route vers l’infini.",
        "Les données racontent des histoires à qui sait les écouter.",
        "La rigueur ouvre la voie à la créativité.",
        "Maths, finance, informatique : un même langage, la logique.",
        "Construire aujourd’hui des systèmes utiles et durables.",
        "La justesse avant la vitesse.",
        "La musique m’apprend l’harmonie, la tech m’apprend la structure.",
      ],
      en: [
        "Self-doubt keeps you motionless, but self-trust opens the path to infinity.",
        "Data tells a story to those who listen.",
        "Rigor is the path to creativity.",
        "Math, finance, and code share one language: logic.",
        "Building useful and sustainable systems.",
        "Accuracy before speed.",
        "Music teaches harmony, tech teaches structure.",
      ],
    }),
    []
  );

  const lang = (i18n.language || "fr").startsWith("fr") ? "fr" : "en";
  const list = QUOTES[lang];
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setIdx((i) => (i + 1) % list.length);
    }, 7000); // change toutes les 7s
    return () => clearInterval(id);
  }, [list.length]);

  return (
    <div className="mt-4 text-center">
      <AnimatePresence mode="wait">
        <motion.p
          key={idx}
          initial={{ opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -6 }}
          transition={{ duration: 0.35 }}
          className="inline-flex items-center gap-2 text-sm italic text-muted px-3 py-1 rounded-full border border-slate-200 dark:border-slate-800 bg-white/60 dark:bg-gray-900/60 backdrop-blur"
        >
          <span aria-hidden>“</span>
          {list[idx]}
          <span aria-hidden>”</span>
        </motion.p>
      </AnimatePresence>
    </div>
  );
}
