import { useTranslation } from "react-i18next";
import { motion } from "framer-motion";

const Dot = () => (
  <span className="mt-2 h-2 w-2 rounded-full bg-indigo-500 inline-block" />
);

export default function CareerGoals() {
  const { i18n } = useTranslation();
  const lang = (i18n.language || "fr").startsWith("fr") ? "fr" : "en";

  const content = lang === "fr"
    ? {
        title: "Objectif de carrière",
        intro:
          "Construire un profil d’ingénieure Data solide, évoluer vers la Data Science appliquée, et transmettre par la pédagogie.",
        stages: [
          {
            tag: "0 – 2 ans",
            items: [
              "Ingénieure Data (pipelines temps réel, ETL/ELT, APIs).",
              "MLOps pragmatique (CI/CD, traçabilité, monitoring).",
              "Certification ciblée (ex. Azure Data, Kafka, dbt).",
            ],
          },
          {
            tag: "2 – 4 ans",
            items: [
              "Spécialisation Data Science (ML, NLP, évaluation & industrialisation).",
              "Conception de data products mesurables (KPIs, ROI).",
              "Contribution open-source / conférences techniques.",
            ],
          },
          {
            tag: "4+ ans",
            items: [
              "Leadership technique (référente Data/ML).",
              "Enseignement / mentoring (cours, workshops, articles).",
              "Vision data-driven au service d’impacts concrets.",
            ],
          },
        ],
      }
    : {
        title: "Career Objective",
        intro:
          "Build a strong Data Engineering profile, grow into applied Data Science, and contribute through teaching.",
        stages: [
          {
            tag: "0 – 2 yrs",
            items: [
              "Data Engineer (real-time pipelines, ETL/ELT, APIs).",
              "Pragmatic MLOps (CI/CD, lineage, monitoring).",
              "Targeted certification (e.g., Azure Data, Kafka, dbt).",
            ],
          },
          {
            tag: "2 – 4 yrs",
            items: [
              "Data Science focus (ML, NLP, evaluation & production).",
              "Design measurable data products (KPIs, ROI).",
              "Open-source contributions / tech talks.",
            ],
          },
          {
            tag: "4+ yrs",
            items: [
              "Technical leadership (Data/ML lead).",
              "Teaching / mentoring (courses, workshops, articles).",
              "Data-driven vision with real impact.",
            ],
          },
        ],
      };

  return (
    <section id="career" className="container section">
      <motion.h2
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="section-title"
      >
        {content.title}
      </motion.h2>

      <motion.p
        initial={{ opacity: 0, y: 10 }}
        whileInView={{ opacity: 1, y: 0 }}
        className="text-slate-700 dark:text-slate-300 max-w-3xl"
      >
        {content.intro}
      </motion.p>

      <div className="mt-8 grid gap-6 md:grid-cols-3">
        {content.stages.map((stage) => (
          <motion.div
            key={stage.tag}
            initial={{ opacity: 0, y: 12 }}
            whileInView={{ opacity: 1, y: 0 }}
            className="card p-6"
          >
            <div className="flex items-center gap-2 text-sm font-semibold text-indigo-600 dark:text-indigo-400">
              <Dot /> <span>{stage.tag}</span>
            </div>
            <ul className="mt-4 space-y-2 text-sm text-slate-700 dark:text-slate-300">
              {stage.items.map((it) => (
                <li key={it} className="flex gap-2">
                  <span className="mt-[6px] h-[6px] w-[6px] rounded-full bg-slate-300 dark:bg-slate-600 inline-block" />
                  <span>{it}</span>
                </li>
              ))}
            </ul>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
